hl.config({
    general = {
        --screen_shader = "$HOME/.config/hypr/shaders/vivid.glsl",

        col = {

            active_border   = "rgba(0a0a0add)",
            inactive_border = "rgba(0a0a0add)",
        },

        resize_on_border = true,
        allow_tearing    = false,
    },
})

-- Blur and window options are generated by the Quickshell shell (Settings > Appearance).
-- Edit them there, not in decoration/blur.lua or decoration/window.lua.
for _, name in ipairs({ "blur", "window" }) do
    local ok, err = pcall(require, "modules.decoration." .. name)
    if not ok then
        print("decoration: could not load " .. name .. ".lua: " .. tostring(err))
    end
end